    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('41fa40e8-912c-469e-8d25-566677ca240c', a_id, $bp$Why does the Author's Word say people's search for solutions in systems and self-effort only deepens the unrest?$bp$, $bp$Pourquoi le Mot de l'auteur dit-il que la recherche de solutions dans les systèmes et l'effort personnel ne fait qu'aggraver le malaise ?$bp$, 0, 1, 3),
      ('40833b1f-fd48-48f9-8067-ac05508aef5b', a_id, $bp$What does the Author's Word say to expect as you carry the Kingdom?$bp$, $bp$Que dit le Mot de l'auteur à quoi s'attendre quand vous portez le Royaume ?$bp$, 1, 1, 3),
      ('3b2819ba-5b84-4391-b799-778ea698de7b', a_id, $bp$How does the Introduction describe repentance as the starting point?$bp$, $bp$Comment l'Introduction décrit-elle la repentance comme point de départ ?$bp$, 2, 1, 3),
      ('d9d44e4a-f41a-4f6f-af67-b4c43338a312', a_id, $bp$What does the book say about people trying to fix the ache with money, power, and knowledge?$bp$, $bp$Que dit le livre des gens qui essaient de guérir le malaise par l'argent, le pouvoir et la connaissance ?$bp$, 3, 1, 3),
      ('8697a7e0-0b90-41b4-92db-8c6c078f12e3', a_id, $bp$How does the book say the door reverses what went wrong in the garden?$bp$, $bp$Comment le livre dit-il que la porte renverse ce qui a mal tourné dans le jardin ?$bp$, 4, 1, 3),
      ('8623d67e-acd2-4769-8350-53b84b6119ba', a_id, $bp$What does the book say Jesus' announcement "the kingdom of God is at hand" means?$bp$, $bp$Que signifie, selon le livre, l'annonce de Jésus « le royaume de Dieu est proche » ?$bp$, 5, 1, 3),
      ('f5c016d7-8ed6-4d96-8bb0-563d1b47822e', a_id, $bp$What does the book say repentance requires you to admit?$bp$, $bp$Que dit le livre que la repentance vous demande de reconnaître ?$bp$, 6, 1, 3),
      ('8b6bc0df-a9e6-4ecf-857c-909ac5b79520', a_id, $bp$What difference does the book say there is between godly sorrow and the sorrow of the world?$bp$, $bp$Quelle différence le livre dit-il qu'il y a entre la tristesse selon Dieu et la tristesse du monde ?$bp$, 7, 1, 3),
      ('f330c730-0d66-4892-af96-2ab6354937f2', a_id, $bp$What does the book say King David's repentance shows?$bp$, $bp$Que montre, selon le livre, la repentance du roi David ?$bp$, 8, 1, 3),
      ('0e31b7af-baae-4b52-a445-ac9c7a1bb573', a_id, $bp$According to the book, what did Peter do differently from Judas after failing Jesus?$bp$, $bp$Selon le livre, qu'a fait Pierre de différent de Judas après avoir failli envers Jésus ?$bp$, 9, 1, 3),
      ('65062585-f55c-43cf-9de2-6a16bfbc4ffe', a_id, $bp$In the book, what does going under the water say about the old life, and what does coming up say?$bp$, $bp$Dans le livre, que dit le fait de descendre sous l'eau de l'ancienne vie, et que dit le fait de remonter ?$bp$, 10, 1, 3),
      ('893a68ec-be22-4f7b-8b6f-40b2e7456a44', a_id, $bp$Why does the book say Jesus was baptized even though He had no old life to bury?$bp$, $bp$Pourquoi le livre dit-il que Jésus a été baptisé alors qu'il n'avait aucune ancienne vie à ensevelir ?$bp$, 11, 1, 3),
      ('d29d593a-0cf8-46a2-91ce-c38ea8b0968d', a_id, $bp$What does the book say about the Philippian jailer's baptism?$bp$, $bp$Que dit le livre du baptême du geôlier de Philippes ?$bp$, 12, 1, 3),
      ('806be76a-54a7-4aef-ac35-780d1a693657', a_id, $bp$What does the book say the Ministry will do for those who have not yet been baptized?$bp$, $bp$Que dit le livre que le Ministère fera pour ceux qui n'ont pas encore été baptisés ?$bp$, 13, 1, 3),
      ('d6b69afd-4911-40c1-96ce-bd8e95c0c0c0', a_id, $bp$What does the book say about Peter before and after the Holy Spirit came?$bp$, $bp$Que dit le livre de Pierre avant et après la venue du Saint-Esprit ?$bp$, 14, 1, 3),
      ('00f57d66-a917-4da0-8585-09e5ccb2fc88', a_id, $bp$What does the book say happened to the Ephesian believers, and what was their situation?$bp$, $bp$Que dit le livre qu'il est arrivé aux croyants d'Éphèse, et quelle était leur situation ?$bp$, 15, 1, 3),
      ('e4718cd5-7f82-42f0-b024-ef009a0f2119', a_id, $bp$What does the book say it means that believers are "sealed" with the Holy Spirit?$bp$, $bp$Que dit le livre du fait que les croyants sont « scellés » du Saint-Esprit ?$bp$, 16, 1, 3),
      ('1d06d2dc-b615-4e87-8b78-6883be2b8c56', a_id, $bp$Which statement matches the common thread in all the examples of the Spirit coming?$bp$, $bp$Quelle affirmation correspond au fil conducteur de tous les exemples de la venue de l'Esprit ?$bp$, 17, 1, 3),
      ('7167a2c8-1184-4d8b-9d05-018dd55cffce', a_id, $bp$What does the book say you were saved for?$bp$, $bp$Que dit le livre que vous avez été sauvé pour faire ?$bp$, 18, 1, 3),
      ('65697159-b24b-48f0-81f1-04d8327d002d', a_id, $bp$What does the book say the ache was pointing you to all along?$bp$, $bp$Que dit le livre vers quoi le malaise vous orientait depuis toujours ?$bp$, 19, 1, 3),
      ('977a2e53-b638-463c-aeb2-88200a9848d7', a_id, $bp$The book teaches that the serpent presented his lie as something obviously evil.$bp$, $bp$Le livre enseigne que le serpent a présenté son mensonge comme quelque chose d'évidemment mauvais.$bp$, 20, 1, 3),
      ('5b320ee0-84a4-4de1-8227-438239f8bf45', a_id, $bp$The book teaches that someone else can make the turn of repentance on your behalf.$bp$, $bp$Le livre enseigne que quelqu'un d'autre peut faire à votre place le retournement de la repentance.$bp$, 21, 1, 3),
      ('5dcb8408-8ba5-417f-9f31-3c760066d78a', a_id, $bp$The book teaches that belief comes first, then baptism, so baptism is never done to someone without their understanding.$bp$, $bp$Le livre enseigne que la foi vient d'abord, puis le baptême, donc le baptême n'est jamais fait à quelqu'un sans qu'il comprenne.$bp$, 22, 1, 3),
      ('24bdfbe3-16db-4ed0-abc1-3a8d32ed2348', a_id, $bp$The book teaches that the Holy Spirit helps you pray, so when you do not know what to pray, He does.$bp$, $bp$Le livre enseigne que le Saint-Esprit vous aide à prier, donc quand vous ne savez pas quoi prier, c'est lui qui le fait.$bp$, 23, 1, 3),
      ('9030da64-a8a3-41e5-a1f8-0725801c6c5c', a_id, $bp$The book teaches that the Rights of Kingdom Citizens series shows what belongs to you, and the Keys of the Kingdom series shows how to live it out.$bp$, $bp$Le livre enseigne que la série Les Droits des citoyens du Royaume montre ce qui vous appartient, et que la série Les Clés du Royaume montre comment le vivre.$bp$, 24, 1, 3);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('3873e0f5-679d-4631-9cd9-0a359176ab67', '41fa40e8-912c-469e-8d25-566677ca240c', $bp$Their troubles are symptoms of lives lived apart from Heaven's rule, which systems cannot reach$bp$, $bp$Leurs ennuis sont des symptômes de vies vécues loin du règne du Ciel, que les systèmes ne peuvent atteindre$bp$, TRUE, 0),
      ('dba7bd17-3ce5-4241-a6a7-46fc4bdd37a6', '41fa40e8-912c-469e-8d25-566677ca240c', $bp$Their systems are badly built, and better planning would remove the troubles in time$bp$, $bp$Leurs systèmes sont mal construits, et une meilleure planification supprimerait les ennuis avec le temps$bp$, FALSE, 1),
      ('4dfdd4c1-8f58-4715-95e5-a8fa7b828ab5', '41fa40e8-912c-469e-8d25-566677ca240c', $bp$Their efforts are too small, and greater effort would eventually solve the whole problem for every person on earth$bp$, $bp$Leurs efforts sont trop petits, et un plus grand effort finirait par résoudre tout le problème pour chaque personne sur terre$bp$, FALSE, 2),
      ('003d2fff-2acc-46e5-b859-5c75b4ee5a70', '41fa40e8-912c-469e-8d25-566677ca240c', $bp$Their leaders are weak, and wiser rulers would bring peace to the nations of the earth$bp$, $bp$Leurs dirigeants sont faibles, et des gouvernants plus sages apporteraient la paix aux nations de la terre$bp$, FALSE, 3),
      ('058131f4-b7f7-45b0-8dd3-7da5a3c51bad', '40833b1f-fd48-48f9-8067-ac05508aef5b', $bp$Rewards: a quick increase in wealth is the proof that your calling is real$bp$, $bp$Des récompenses : une rapide augmentation de richesse est la preuve que votre appel est réel$bp$, FALSE, 0),
      ('d2e66480-4569-4ccc-8740-ffbb08bb80e2', '40833b1f-fd48-48f9-8067-ac05508aef5b', $bp$Silence: the world will ignore you and leave you alone to serve in peace$bp$, $bp$Le silence : le monde vous ignorera et vous laissera servir en paix$bp$, FALSE, 1),
      ('ad71a4c9-dd70-4a77-8502-075d7d2de06d', '40833b1f-fd48-48f9-8067-ac05508aef5b', $bp$Resistance: opposition is often confirmation of the value of what you carry$bp$, $bp$La résistance : l'opposition est souvent la confirmation de la valeur de ce que vous portez$bp$, TRUE, 2),
      ('d2e4fc27-dd7e-4478-b09c-bb403e50463b', '40833b1f-fd48-48f9-8067-ac05508aef5b', $bp$Comfort: favour from everyone is confirmation that you are walking with God$bp$, $bp$Le confort : la faveur de tous est la confirmation que vous marchez avec Dieu$bp$, FALSE, 3),
      ('114842e7-8276-46e6-b849-fa1db2fc258f', '3b2819ba-5b84-4391-b799-778ea698de7b', $bp$It is the end of salvation and the proof that a believer has become fully mature$bp$, $bp$Elle est la fin du salut et la preuve qu'un croyant est devenu pleinement mûr$bp$, FALSE, 0),
      ('3495526e-ebb9-4304-90ff-7ec9fe3a6453', '3b2819ba-5b84-4391-b799-778ea698de7b', $bp$It is the cost of salvation and the price that a believer must pay in advance$bp$, $bp$Elle est le coût du salut et le prix qu'un croyant doit payer d'avance$bp$, FALSE, 1),
      ('3a903643-4cdd-4f68-9888-8c452c63fc7b', '3b2819ba-5b84-4391-b799-778ea698de7b', $bp$It is the reward of salvation and the sign that a believer has been fully forgiven of all sins$bp$, $bp$Elle est la récompense du salut et le signe qu'un croyant a été pleinement pardonné de tous ses péchés$bp$, FALSE, 2),
      ('471bf1c7-8c48-45d7-bf51-c1bf6ec61adb', '3b2819ba-5b84-4391-b799-778ea698de7b', $bp$It is the threshold of salvation and the beginning of a renewed Kingdom consciousness$bp$, $bp$Elle est le seuil du salut et le commencement d'une conscience du Royaume renouvelée$bp$, TRUE, 3),
      ('04a4ec1d-ccf2-4de7-bcac-2e8a21c193f0', 'd9d44e4a-f41a-4f6f-af67-b4c43338a312', $bp$Each one helps the rich, but never the poor, who lack the means to use them$bp$, $bp$Chacun aide les riches, mais jamais les pauvres, qui n'ont pas les moyens de s'en servir$bp$, FALSE, 0),
      ('7a2391bb-4cdd-4d6c-9cbd-78623285a733', 'd9d44e4a-f41a-4f6f-af67-b4c43338a312', $bp$Each one works, but only for a short time, until the next problem comes along$bp$, $bp$Chacun fonctionne, mais seulement un court moment, jusqu'à ce que le problème suivant arrive$bp$, FALSE, 1),
      ('2393df13-ce80-4411-99d5-ca040ca792a3', 'd9d44e4a-f41a-4f6f-af67-b4c43338a312', $bp$Each promises to fix the unrest but adds to it, because something deeper is broken$bp$, $bp$Chacun promet de guérir le malaise mais l'aggrave, parce que quelque chose de plus profond est brisé$bp$, TRUE, 2),
      ('2ee7cdf5-cdaf-46cc-88ad-f77b25ba8e32', 'd9d44e4a-f41a-4f6f-af67-b4c43338a312', $bp$Each one is wrong, because God does not want a believer to have money or power in their lives$bp$, $bp$Chacun est dans l'erreur, parce que Dieu ne veut pas qu'un croyant ait de l'argent ou du pouvoir dans sa vie$bp$, FALSE, 3),
      ('d7aa6b91-2e67-4fe2-bcfa-0fc3f32294ba', '8697a7e0-0b90-41b4-92db-8c6c078f12e3', $bp$Right works replace wrong works, and God's blessing in the home replaces the curse of the ground and the pain of labour$bp$, $bp$Les bonnes œuvres remplacent les mauvaises, et la bénédiction de Dieu dans la maison remplace la malédiction du sol et la peine du travail$bp$, FALSE, 0),
      ('e0dc705f-4c7e-43d7-b020-8a9001bf0c9a', '8697a7e0-0b90-41b4-92db-8c6c078f12e3', $bp$Right words replace wrong words, and God's voice in the church replaces silence from Heaven$bp$, $bp$Les bonnes paroles remplacent les mauvaises, et la voix de Dieu dans l'Église remplace le silence du Ciel$bp$, FALSE, 1),
      ('ede90253-cbc9-40e1-891a-cbe106bdb1ae', '8697a7e0-0b90-41b4-92db-8c6c078f12e3', $bp$Right laws replace wrong laws, and God's rule in the nation replaces the rule of the enemy$bp$, $bp$Les bonnes lois remplacent les mauvaises, et le règne de Dieu dans la nation remplace le règne de l'ennemi$bp$, FALSE, 2),
      ('d84370f2-cd23-4b39-b28b-5ad80b7676bc', '8697a7e0-0b90-41b4-92db-8c6c078f12e3', $bp$Right thinking replaces wrong thinking, and God's presence living inside replaces hiding from Him$bp$, $bp$La bonne pensée remplace la mauvaise, et la présence de Dieu qui habite à l'intérieur remplace le fait de se cacher de lui$bp$, TRUE, 3),
      ('9f1b73bb-10e5-4647-8a46-d00debc73688', '8623d67e-acd2-4769-8350-53b84b6119ba', $bp$It is coming soon to the earth, and only the generation then alive will see it$bp$, $bp$Il vient bientôt sur la terre, et seule la génération alors vivante le verra$bp$, FALSE, 0),
      ('d3f24a82-848d-4ee2-932a-4b4214557773', '8623d67e-acd2-4769-8350-53b84b6119ba', $bp$It is real and available right now, and not only a hope for after we die$bp$, $bp$Il est réel et accessible dès maintenant, et pas seulement une espérance pour après la mort$bp$, TRUE, 1),
      ('68ddbcc0-b454-4365-952b-0c24394f9eaf', '8623d67e-acd2-4769-8350-53b84b6119ba', $bp$It is available only to those who first keep the law and prove they are worthy$bp$, $bp$Il n'est accessible qu'à ceux qui gardent d'abord la loi et prouvent qu'ils en sont dignes$bp$, FALSE, 2),
      ('af58908e-f487-4ca6-ba4a-d90646961959', '8623d67e-acd2-4769-8350-53b84b6119ba', $bp$It is near but unreachable for now, and only a hope that will come to us later$bp$, $bp$Il est proche mais inaccessible pour le moment, et seulement une espérance qui viendra plus tard$bp$, FALSE, 3),
      ('fa722704-07a8-4a60-ac6d-5f5079e2f09a', 'f5c016d7-8ed6-4d96-8bb0-563d1b47822e', $bp$That everyone has sinned, that sin leads to death, and that only Jesus' blood forgives$bp$, $bp$Que tous ont péché, que le péché mène à la mort, et que seul le sang de Jésus pardonne$bp$, TRUE, 0),
      ('f746573a-8080-46a0-ba94-029b72bb8e8c', 'f5c016d7-8ed6-4d96-8bb0-563d1b47822e', $bp$That your parents have sinned, that curses run in families, and that only a priest forgives$bp$, $bp$Que vos parents ont péché, que les malédictions se transmettent dans les familles, et que seul un prêtre pardonne$bp$, FALSE, 1),
      ('36b8e2e2-c03f-4ec0-a7e3-500779a3b352', 'f5c016d7-8ed6-4d96-8bb0-563d1b47822e', $bp$That some people have sinned, that sin leads to loss, and that only time and effort forgive$bp$, $bp$Que certaines personnes ont péché, que le péché mène à la perte, et que seuls le temps et l'effort pardonnent$bp$, FALSE, 2),
      ('519ff875-2e53-4952-a853-e1ca6b03343d', 'f5c016d7-8ed6-4d96-8bb0-563d1b47822e', $bp$That most people have sinned, that sin leads to shame, and that only good works forgive$bp$, $bp$Que la plupart des gens ont péché, que le péché mène à la honte, et que seules les bonnes œuvres pardonnent$bp$, FALSE, 3),
      ('0db8c5dc-3fec-4693-806f-a2a6fe122c2d', '8b6bc0df-a9e6-4ecf-857c-909ac5b79520', $bp$Godly sorrow is quiet and private, while the sorrow of the world is loud and public before the church$bp$, $bp$La tristesse selon Dieu est silencieuse et privée, tandis que la tristesse du monde est bruyante et publique devant l'Église$bp$, FALSE, 0),
      ('8866e284-96cc-42e4-9442-526bbaf2744e', '8b6bc0df-a9e6-4ecf-857c-909ac5b79520', $bp$Godly sorrow works repentance leading to salvation, while the sorrow of the world works death$bp$, $bp$La tristesse selon Dieu produit une repentance qui mène au salut, tandis que la tristesse du monde produit la mort$bp$, TRUE, 1),
      ('cc6d2a0f-1cd7-4c35-b887-840f86f557b0', '8b6bc0df-a9e6-4ecf-857c-909ac5b79520', $bp$Godly sorrow comes from leaders, while the sorrow of the world comes from followers$bp$, $bp$La tristesse selon Dieu vient des dirigeants, tandis que la tristesse du monde vient de ceux qui suivent$bp$, FALSE, 2),
      ('195d73f5-792c-4fe0-ac6f-b517a04a1ea9', '8b6bc0df-a9e6-4ecf-857c-909ac5b79520', $bp$Godly sorrow lasts a long time, while the sorrow of the world lasts only a few days$bp$, $bp$La tristesse selon Dieu dure longtemps, tandis que la tristesse du monde ne dure que quelques jours$bp$, FALSE, 3),
      ('4361b735-09e3-4034-86f1-fd7c635b90d6', 'f330c730-0d66-4892-af96-2ab6354937f2', $bp$He felt deep embarrassment, hid his sin for a time, and prayed to be kept from shame$bp$, $bp$Il a ressenti une profonde gêne, a caché son péché un temps, et a prié d'être gardé de la honte$bp$, FALSE, 0),
      ('8600de46-dbab-48b4-a100-fa3219a5d49b', 'f330c730-0d66-4892-af96-2ab6354937f2', $bp$He explained his sin well, defended his reasons, and prayed to be forgiven and restored$bp$, $bp$Il a bien expliqué son péché, défendu ses raisons, et prié d'être pardonné et rétabli$bp$, FALSE, 1),
      ('875ec3bd-37e8-4d22-846d-664d37a8837e', 'f330c730-0d66-4892-af96-2ab6354937f2', $bp$He admitted and owned his sin fully, never repeated it, and prayed for a completely new heart$bp$, $bp$Il a reconnu et assumé pleinement son péché, ne l'a jamais répété, et a prié pour un cœur entièrement nouveau$bp$, TRUE, 2),
      ('047ac575-e999-4312-bbd9-0b9f9da21a40', 'f330c730-0d66-4892-af96-2ab6354937f2', $bp$He confessed to the nation, paid a fine for his sin, and prayed that God would bless him$bp$, $bp$Il a confessé devant la nation, payé une amende pour son péché, et prié que Dieu le bénisse$bp$, FALSE, 3),
      ('abff0c3c-f35f-433f-99b8-3b2e70667df9', '0e31b7af-baae-4b52-a445-ac9c7a1bb573', $bp$Peter returned the money to the chief priests, while Judas returned to his old trade$bp$, $bp$Pierre a rendu l'argent aux grands prêtres, tandis que Judas est retourné à son ancien métier$bp$, FALSE, 0),
      ('de65d0f9-0024-4ac5-872f-a11f3fec3be5', '0e31b7af-baae-4b52-a445-ac9c7a1bb573', $bp$Peter went back to the other disciples and was restored, while Judas went the other way$bp$, $bp$Pierre est retourné vers les autres disciples et a été rétabli, tandis que Judas est parti dans l'autre direction$bp$, TRUE, 1),
      ('407dbb26-1141-40a5-a697-74c79db9af03', '0e31b7af-baae-4b52-a445-ac9c7a1bb573', $bp$Peter wept alone and was forgotten, while Judas was remembered and honoured by them$bp$, $bp$Pierre a pleuré seul et a été oublié, tandis que Judas a été rappelé et honoré par eux$bp$, FALSE, 2),
      ('60283791-bf63-403a-a06a-fb1b6d742f6b', '0e31b7af-baae-4b52-a445-ac9c7a1bb573', $bp$Peter hid from the other disciples for a long time, while Judas returned to them$bp$, $bp$Pierre s'est caché des autres disciples pendant longtemps, tandis que Judas est retourné vers eux$bp$, FALSE, 3),
      ('d941980c-c410-4c00-983b-059f82848e46', '65062585-f55c-43cf-9de2-6a16bfbc4ffe', $bp$Going under says you are washed of sin; coming up says you are free from all trouble$bp$, $bp$Descendre dit que vous êtes lavé du péché ; remonter dit que vous êtes libre de tout ennui$bp$, FALSE, 0),
      ('df7c3dfa-1ebb-47e1-ac16-9b393ea729b8', '65062585-f55c-43cf-9de2-6a16bfbc4ffe', $bp$Going under says you are alone; coming up says you have joined a church community$bp$, $bp$Descendre dit que vous êtes seul ; remonter dit que vous avez rejoint une communauté d'Église$bp$, FALSE, 1),
      ('365fa429-7944-4ad7-9061-9de54b54d366', '65062585-f55c-43cf-9de2-6a16bfbc4ffe', $bp$Going under says you are weak; coming up says you have been made strong by the church$bp$, $bp$Descendre dit que vous êtes faible ; remonter dit que l'Église vous a rendu fort$bp$, FALSE, 2),
      ('f9cdd514-cb48-4558-9c92-70389d695965', '65062585-f55c-43cf-9de2-6a16bfbc4ffe', $bp$Going under says the old life ended with Christ; coming up says a new life has begun$bp$, $bp$Descendre dit que l'ancienne vie a pris fin avec Christ ; remonter dit qu'une vie nouvelle a commencé$bp$, TRUE, 3),
      ('53caf372-d4e6-4797-b6e8-8c547e79f0fb', '893a68ec-be22-4f7b-8b6f-40b2e7456a44', $bp$To cleanse the river Jordan, and to make all later baptisms holy in God's sight$bp$, $bp$Pour purifier le Jourdain et rendre saints aux yeux de Dieu tous les baptêmes suivants$bp$, FALSE, 0),
      ('34940d5d-03fa-4c19-96f9-8ab57fc12205', '893a68ec-be22-4f7b-8b6f-40b2e7456a44', $bp$To join the crowd of sinners, and to receive His authority from John the Baptist$bp$, $bp$Pour se joindre à la foule des pécheurs et recevoir son autorité de Jean-Baptiste$bp$, FALSE, 1),
      ('541b2ec5-1cc4-4369-84cc-bb20663fc290', '893a68ec-be22-4f7b-8b6f-40b2e7456a44', $bp$To show that even a sinless man must repent, and to teach John how to baptize$bp$, $bp$Pour montrer que même un homme sans péché doit se repentir et pour apprendre à Jean comment baptiser$bp$, FALSE, 2),
      ('d67c30d6-20b3-4f4e-b897-495cf7c55561', '893a68ec-be22-4f7b-8b6f-40b2e7456a44', $bp$To set the pattern for everyone who would follow Him, and to fulfil all righteousness$bp$, $bp$Pour donner l'exemple à tous ceux qui le suivraient et pour accomplir toute justice$bp$, TRUE, 3),
      ('239627a8-5428-427b-92cb-7bb886ff7307', 'd29d593a-0cf8-46a2-91ce-c38ea8b0968d', $bp$He was baptized alone, since his household did not yet believe what Paul had said$bp$, $bp$Il a été baptisé seul, puisque sa maison ne croyait pas encore ce que Paul avait dit$bp$, FALSE, 0),
      ('13f445b4-75b8-43cf-a79e-7c35fd0a0f44', 'd29d593a-0cf8-46a2-91ce-c38ea8b0968d', $bp$He asked to be baptized at once, but Paul sent him away until the morning came$bp$, $bp$Il a demandé à être baptisé tout de suite, mais Paul l'a renvoyé jusqu'au matin$bp$, FALSE, 1),
      ('8d2af011-83b0-4710-a314-713c00b8a12d', 'd29d593a-0cf8-46a2-91ce-c38ea8b0968d', $bp$He believed in the middle of the night, and he and all his were baptized straightway$bp$, $bp$Il a cru au milieu de la nuit, et lui et tous les siens ont été baptisés aussitôt$bp$, TRUE, 2),
      ('4285446b-f48d-4043-a133-0c847c70689f', 'd29d593a-0cf8-46a2-91ce-c38ea8b0968d', $bp$He waited three days to be taught, and then he and all his were baptized in the river$bp$, $bp$Il a attendu trois jours pour être instruit, puis lui et tous les siens ont été baptisés dans le fleuve$bp$, FALSE, 3),
      ('6485fc1d-ac8d-4228-aa3f-dc922c40a168', '806be76a-54a7-4aef-ac35-780d1a693657', $bp$Wait for them to come to a church building, where a minister will baptize them$bp$, $bp$Les attendre dans un bâtiment d'église, où un ministre les baptisera$bp$, FALSE, 0),
      ('ee8f1ada-52f7-47dc-bff2-21d4ddd75de1', '806be76a-54a7-4aef-ac35-780d1a693657', $bp$Place them in a class for several months, until they have learned enough to be baptized$bp$, $bp$Les placer dans une classe pendant plusieurs mois, jusqu'à ce qu'ils en sachent assez pour être baptisés$bp$, FALSE, 1),
      ('893c187e-f006-4012-b887-339a4810856c', '806be76a-54a7-4aef-ac35-780d1a693657', $bp$Help them find someone to baptize them wherever they are, as soon as they are able$bp$, $bp$Les aider à trouver quelqu'un pour les baptiser là où ils sont, dès qu'ils le peuvent$bp$, TRUE, 2),
      ('83ca2e0f-72bb-42ba-9e3e-e56d217f1254', '806be76a-54a7-4aef-ac35-780d1a693657', $bp$Send them to a church in their own area, and leave them to arrange it themselves$bp$, $bp$Les envoyer vers une église de leur région et les laisser s'arranger eux-mêmes$bp$, FALSE, 3),
      ('43347b4e-21ad-45e6-9427-b8facbe17c6d', 'd6b69afd-4911-40c1-96ce-bd8e95c0c0c0', $bp$A different man who was always bold gave up his fear, with the very same power source$bp$, $bp$Un homme différent, toujours hardi, a abandonné sa peur, avec la même source de puissance$bp$, FALSE, 0),
      ('a46a03f2-3e50-43fd-a8d3-1c2b8f383768', 'd6b69afd-4911-40c1-96ce-bd8e95c0c0c0', $bp$The same man who hid in fear became bold, with a completely different power source$bp$, $bp$Le même homme qui se cachait de peur est devenu hardi, avec une source de puissance entièrement différente$bp$, TRUE, 1),
      ('e2cd2390-0e4a-4e2c-96ee-d15ab4aaf364', 'd6b69afd-4911-40c1-96ce-bd8e95c0c0c0', $bp$The same man who was always strong grew stronger, with the support of the other apostles$bp$, $bp$Le même homme toujours fort est devenu plus fort, avec le soutien des autres apôtres$bp$, FALSE, 2),
      ('e0dc9bc1-444c-4f91-91cc-fb5d007b5d75', 'd6b69afd-4911-40c1-96ce-bd8e95c0c0c0', $bp$The same man who preached in boldness became afraid, with a completely different message$bp$, $bp$Le même homme qui prêchait avec hardiesse a eu peur, avec un message entièrement différent$bp$, FALSE, 3),
      ('986a9e57-8c83-4f42-9160-3856aaf7e4e3', '00f57d66-a917-4da0-8585-09e5ccb2fc88', $bp$They had never heard of the Holy Spirit; when Paul prayed, they spoke with tongues and prophesied$bp$, $bp$Ils n'avaient jamais entendu parler du Saint-Esprit ; quand Paul a prié, ils ont parlé en langues et prophétisé$bp$, TRUE, 0),
      ('2a05ab5d-6202-4a63-b978-49b3bcefc499', '00f57d66-a917-4da0-8585-09e5ccb2fc88', $bp$They had heard of the Spirit; when Paul taught, they understood and began to preach$bp$, $bp$Ils avaient entendu parler de l'Esprit ; quand Paul a enseigné, ils ont compris et se sont mis à prêcher$bp$, FALSE, 1),
      ('2aad7b83-5fe5-49dd-8fd4-be36a4272821', '00f57d66-a917-4da0-8585-09e5ccb2fc88', $bp$They had lost the Holy Spirit; when Paul prayed, they were healed and filled with joy$bp$, $bp$Ils avaient perdu le Saint-Esprit ; quand Paul a prié, ils ont été guéris et remplis de joie$bp$, FALSE, 2),
      ('e750e728-ebeb-4a2d-8d0e-e6e5cde68b42', '00f57d66-a917-4da0-8585-09e5ccb2fc88', $bp$They had refused the Holy Spirit; when Paul prayed, they wept and asked for forgiveness from God and from others$bp$, $bp$Ils avaient refusé le Saint-Esprit ; quand Paul a prié, ils ont pleuré et demandé pardon à Dieu et aux autres$bp$, FALSE, 3),
      ('4d526282-cea8-4ac4-b847-9daf9c293681', 'e4718cd5-7f82-42f0-b024-ef009a0f2119', $bp$A seal marks something as closed and hidden: God's way of keeping the believer from harm and from all trouble$bp$, $bp$Un sceau marque une chose comme fermée et cachée : la manière dont Dieu garde le croyant de tout mal et de tout ennui$bp$, FALSE, 0),
      ('d6164ebb-8a3b-4e15-9f7c-1e79d94bb7c3', 'e4718cd5-7f82-42f0-b024-ef009a0f2119', $bp$A seal marks something as finished and complete: God's proof that growth has ended$bp$, $bp$Un sceau marque une chose comme finie et complète : la preuve de Dieu que la croissance est terminée$bp$, FALSE, 1),
      ('8b7a2759-d4b1-4e2e-a0d4-0306326f11d4', 'e4718cd5-7f82-42f0-b024-ef009a0f2119', $bp$A seal marks something as secret and sacred: God's sign that the church is above others$bp$, $bp$Un sceau marque une chose comme secrète et sacrée : le signe de Dieu que l'Église est au-dessus des autres$bp$, FALSE, 2),
      ('f2c4cf13-89f2-4743-ac4d-c31af55b058b', 'e4718cd5-7f82-42f0-b024-ef009a0f2119', $bp$A seal marks something as official and owned: God's confirmation that this one belongs to Him$bp$, $bp$Un sceau marque une chose comme officielle et possédée : la confirmation de Dieu que celui-ci lui appartient$bp$, TRUE, 3),
      ('2702168b-5d11-46eb-83e9-d5ba7382ae3c', '1d06d2dc-b615-4e87-8b78-6883be2b8c56', $bp$He comes to leaders who were chosen, usually in the temple, and it is seen only by them$bp$, $bp$Il vient sur des dirigeants choisis, généralement dans le temple, et eux seuls le voient$bp$, FALSE, 0),
      ('c5dc2e39-49a1-46fd-bf76-e99f2920205f', '1d06d2dc-b615-4e87-8b78-6883be2b8c56', $bp$He comes to those who were baptized, only in the daytime, and it lasts for a short time$bp$, $bp$Il vient sur ceux qui ont été baptisés, seulement de jour, et cela dure peu de temps$bp$, FALSE, 1),
      ('4d3e8f58-e616-4f84-bafc-6d9a011ebd43', '1d06d2dc-b615-4e87-8b78-6883be2b8c56', $bp$He comes to those who repented and believed, often through prayer and laying on of hands, and it shows$bp$, $bp$Il vient sur ceux qui se sont repentis et ont cru, souvent par la prière et l'imposition des mains, et cela se voit$bp$, TRUE, 2),
      ('15b0c29e-ccdd-4e76-a86f-d3f5ff4807d5', '1d06d2dc-b615-4e87-8b78-6883be2b8c56', $bp$He comes to those who fasted and waited, always in a church building, and it is kept quiet from others who are present$bp$, $bp$Il vient sur ceux qui ont jeûné et attendu, toujours dans un bâtiment d'église, et cela reste discret pour les autres présents$bp$, FALSE, 3),
      ('a9265120-03d0-426a-85b1-f0fc8a98ba4a', '7167a2c8-1184-4d8b-9d05-018dd55cffce', $bp$To represent Heaven here on earth, and not just to wait to get to Heaven$bp$, $bp$Représenter le Ciel ici sur la terre, et non pas seulement attendre d'arriver au Ciel$bp$, TRUE, 0),
      ('5f3cc16c-09c7-4562-8b37-64373d6637cf', '7167a2c8-1184-4d8b-9d05-018dd55cffce', $bp$To build a large church on earth, and to bring as many people as possible into it$bp$, $bp$Bâtir une grande église sur la terre et y faire entrer le plus de gens possible$bp$, FALSE, 1),
      ('0b71f0b3-4a82-4a87-9e39-052dfd8e1f66', '7167a2c8-1184-4d8b-9d05-018dd55cffce', $bp$To avoid the world and its influence, and to keep ourselves separate until He returns$bp$, $bp$Éviter le monde et son influence, et nous tenir à l'écart jusqu'à son retour$bp$, FALSE, 2),
      ('b2f8b363-53d9-4248-88c2-1cf38ca5b395', '7167a2c8-1184-4d8b-9d05-018dd55cffce', $bp$To wait for Heaven in peace, and not to get involved in the troubles of the earth$bp$, $bp$Attendre le Ciel en paix, et ne pas nous mêler des ennuis de la terre$bp$, FALSE, 3),
      ('85d99d89-b010-4c73-b360-addf8db145c2', '65697159-b24b-48f0-81f1-04d8327d002d', $bp$A better system, and the invitation to build it with greater effort and wisdom$bp$, $bp$Un meilleur système, et l'invitation à le bâtir avec plus d'effort et de sagesse$bp$, FALSE, 0),
      ('f107a9e9-915d-4d09-8a2a-6dae6732b396', '65697159-b24b-48f0-81f1-04d8327d002d', $bp$The open door, and the invitation to come through it, which was there all along$bp$, $bp$La porte ouverte, et l'invitation à la franchir, qui était là depuis toujours$bp$, TRUE, 1),
      ('17de46a0-374c-4d69-bef5-8de574b11e9c', '65697159-b24b-48f0-81f1-04d8327d002d', $bp$A new teacher, and the invitation to follow him with greater faith and loyalty$bp$, $bp$Un nouveau maître, et l'invitation à le suivre avec plus de foi et de loyauté$bp$, FALSE, 2),
      ('d1b459a2-165d-42ad-a85b-d779938cbd9a', '65697159-b24b-48f0-81f1-04d8327d002d', $bp$A hidden secret, and the invitation to search for it with greater time and study$bp$, $bp$Un secret caché, et l'invitation à le chercher avec plus de temps et d'étude$bp$, FALSE, 3),
      ('130af5d3-f415-46f1-a101-8dd196e79397', '977a2e53-b638-463c-aeb2-88200a9848d7', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('3aa7f4fc-4b67-4db5-9ef0-3feab7bb3fed', '977a2e53-b638-463c-aeb2-88200a9848d7', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('e2bcf9a4-8fc5-45cb-860b-02f7e39be06d', '5b320ee0-84a4-4de1-8227-438239f8bf45', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('59951944-46d0-42eb-be1e-27600b70145f', '5b320ee0-84a4-4de1-8227-438239f8bf45', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('1c132045-5a64-4433-8abb-f1c64edc9f2a', '5dcb8408-8ba5-417f-9f31-3c760066d78a', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('48002b47-1d1a-4be4-abe4-dd327d07b78f', '5dcb8408-8ba5-417f-9f31-3c760066d78a', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('7db075eb-3ac7-41ae-a570-a8cec6ea9666', '24bdfbe3-16db-4ed0-abc1-3a8d32ed2348', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('3242db39-7c58-4b37-a705-33a26f598fbe', '24bdfbe3-16db-4ed0-abc1-3a8d32ed2348', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('5bd94b85-87f2-4a68-8141-232d04ec694b', '9030da64-a8a3-41e5-a1f8-0725801c6c5c', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('c65a53c5-e74e-4e72-89a8-f0c24ffaaf1a', '9030da64-a8a3-41e5-a1f8-0725801c6c5c', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1);
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('1196b3e7-5865-46cc-82e2-e1acecfab877', a_id, 1, 0, 'CHOICE', $bp$Chapter Two says repentance is a change of mind that leads to a change of direction. Have you turned from your old way of living and given your life to Jesus Christ?$bp$, $bp$Le chapitre deux dit que la repentance est un changement d'esprit qui mène à un changement de direction. Vous êtes-vous détourné de votre ancienne manière de vivre et avez-vous donné votre vie à Jésus-Christ ?$bp$, NULL, NULL, $bp$Yes: ask what changed. Not yet, on the way, or not sure: explain that repentance is a decision, not a feeling (Chapter Two). Invite them to pray the Prayer of Repentance from Chapter Two with you.$bp$, $bp$Oui : demandez ce qui a changé. Pas encore, en chemin ou pas sûr : expliquez que la repentance est une décision, pas un sentiment (chapitre deux). Invitez la personne à prier avec vous la prière de repentance du chapitre deux.$bp$, TRUE, FALSE, TRUE),
      ('806c35af-9e12-4c42-972d-1fbc60c0e06a', a_id, 1, 1, 'CHOICE', $bp$Have you been baptized in water by immersion, going fully under the water and coming back up, after you believed in Jesus?$bp$, $bp$Avez-vous été baptisé d'eau par immersion, en descendant entièrement sous l'eau puis en ressortant, après avoir cru en Jésus ?$bp$, NULL, NULL, $bp$Yes, fully immersed after believing: this is the book's pattern (baptidzo means to immerse; Romans 6:3-4). Sprinkled or baptized before believing: gently explain that the book teaches believer's baptism by immersion, and arrange it. Not yet: do not wait; arrange it as soon as possible, as every example in Acts did.$bp$, $bp$Oui, immergé après avoir cru : c'est le modèle du livre (baptidzo signifie immerger ; Romains 6.3-4). Aspergé ou baptisé avant de croire : expliquez avec douceur que le livre enseigne le baptême du croyant par immersion, et organisez-le. Pas encore : n'attendez pas ; organisez-le dès que possible, comme tous les exemples des Actes.$bp$, TRUE, FALSE, TRUE),
      ('2af470ff-cdb5-49f6-b00c-8f1be48cc6cb', a_id, 1, 2, 'TEXT', $bp$If yes, when and where were you baptized, and who baptized you?$bp$, $bp$Si oui, quand et où avez-vous été baptisé, et qui vous a baptisé ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('9b5a8031-638b-4922-8082-ed5ca58485fb', a_id, 1, 3, 'CHOICE', $bp$Have you received the Holy Spirit, with the evidence of speaking in other tongues, as in Acts 2, 10 and 19?$bp$, $bp$Avez-vous reçu le Saint-Esprit, avec pour preuve de parler en d'autres langues, comme en Actes 2, 10 et 19 ?$bp$, NULL, NULL, $bp$Yes with tongues: celebrate. Have the Spirit but no tongues, not yet, or need explaining: teach Luke 11:13 (a gift received by asking), and the examples at Pentecost, Cornelius, and Ephesus where they spoke in tongues. Offer to pray with laying on of hands (Acts 8:17; 19:6).$bp$, $bp$Oui avec les langues : réjouissez-vous. A l'Esprit mais pas de langues, pas encore, ou besoin d'explication : enseignez Luc 11.13 (un don reçu en demandant) et les exemples de la Pentecôte, de Corneille et d'Éphèse où ils ont parlé en langues. Proposez de prier avec imposition des mains (Actes 8.17 ; 19.6).$bp$, TRUE, FALSE, TRUE),
      ('99c8ccda-dc89-4047-9852-275e4eba75da', a_id, 1, 4, 'TEXT', $bp$If yes, when and how did you receive Him?$bp$, $bp$Si oui, quand et comment l'avez-vous reçu ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('5cec0b60-e8ac-4a32-b5a6-499afc69063a', a_id, 1, 5, 'TEXT', $bp$Chapter Two says true repentance produces visible fruit, like Zacchaeus giving back what he took, and Chapter Three says the old life is buried and a new life begins. What has changed in your life and actions since you turned to Christ?$bp$, $bp$Le chapitre deux dit que la vraie repentance produit un fruit visible, comme Zachée rendant ce qu'il avait pris, et le chapitre trois dit que l'ancienne vie est ensevelie et qu'une nouvelle vie commence. Qu'est-ce qui a changé dans votre vie et dans vos actes depuis que vous vous êtes tourné vers Christ ?$bp$, NULL, NULL, $bp$Look for real fruit, as in Zacchaeus: new desire for the Word, freedom, changed habits, something stopped, restored or started. If "nothing yet", have a gentle conversation about what a changed mind should now begin to change.$bp$, $bp$Cherchez un vrai fruit, comme chez Zachée : nouveau désir de la Parole, liberté, habitudes changées, quelque chose arrêté, rendu ou commencé. Si « rien encore », ayez une conversation douce sur ce qu'un esprit changé devrait maintenant commencer à changer.$bp$, TRUE, FALSE, FALSE),
      ('9e4ab147-e822-46d7-94e9-d48edf71b265', a_id, 1, 6, 'CHOICE', $bp$Would you like the God Nation team to help you with the next step?$bp$, $bp$Aimeriez-vous que l'équipe de God Nation vous aide pour la prochaine étape ?$bp$, NULL, NULL, $bp$This is your follow-up list. Use the contact details to arrange baptism and prayer, as the book promises, through The God Nation Baptism and Holy Spirit group.$bp$, $bp$C'est votre liste de suivi. Utilisez les coordonnées pour organiser le baptême et la prière, comme le livre le promet, par le groupe Baptême et Saint-Esprit de The God Nation.$bp$, TRUE, FALSE, FALSE),
      ('0acb79f6-c0ba-41fb-892d-605244cc6c73', a_id, 1, 7, 'TEXT', $bp$Best way to reach you (phone number or email)$bp$, $bp$Meilleur moyen de vous joindre (numéro de téléphone ou e-mail)$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('fa889c19-5903-42ef-b4cc-6626746778f2', a_id, 1, 8, 'TEXT', $bp$What is the one thing, if any, that is holding you back from taking the next step in the doorway (repentance, baptism, or the Holy Spirit)? If nothing, write "nothing".$bp$, $bp$Quelle est la seule chose, s'il y en a une, qui vous retient de franchir la prochaine étape de la porte d'entrée (repentance, baptême ou Saint-Esprit) ? S'il n'y a rien, écrivez « rien ».$bp$, NULL, NULL, $bp$Read this with care and pray over it. Name the barrier gently, and answer it from the book. Note them for follow-up.$bp$, $bp$Lisez avec soin et priez à ce sujet. Nommez doucement l'obstacle et répondez-y à partir du livre. Notez la personne pour un suivi.$bp$, TRUE, TRUE, FALSE),
      ('ef8af630-c828-467e-a76b-209a31ca31d8', a_id, 1, 9, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('4655c254-e732-41f8-bbd4-89b6e6cc318c', '1196b3e7-5865-46cc-82e2-e1acecfab877', 0, $bp$Yes, I have turned, and I have received Jesus as my Lord and Saviour$bp$, $bp$Oui, je me suis détourné, et j'ai reçu Jésus comme mon Seigneur et Sauveur$bp$, 'POSITIVE'),
      ('8355c59e-89e2-4cfb-9400-2eec2b15de54', '1196b3e7-5865-46cc-82e2-e1acecfab877', 1, $bp$I am on the way, but I have not fully turned yet$bp$, $bp$Je suis en chemin, mais je ne me suis pas encore pleinement détourné$bp$, 'NEEDS_TALK'),
      ('39e0bf8a-382f-49a3-af0d-4950f75ef236', '1196b3e7-5865-46cc-82e2-e1acecfab877', 2, $bp$Not yet$bp$, $bp$Pas encore$bp$, 'NEEDS_TALK'),
      ('fef78b7e-2f8e-4c59-a196-71cddcb34f38', '1196b3e7-5865-46cc-82e2-e1acecfab877', 3, $bp$I am not sure what this means for me$bp$, $bp$Je ne suis pas sûr de ce que cela signifie pour moi$bp$, 'NEEDS_TALK'),
      ('fcbb0beb-f87c-47d0-b066-3a7faadf9c06', '806c35af-9e12-4c42-972d-1fbc60c0e06a', 0, $bp$Yes, I was fully immersed in water after I believed$bp$, $bp$Oui, j'ai été entièrement immergé dans l'eau après avoir cru$bp$, 'POSITIVE'),
      ('7c139976-4053-490d-853e-3da04b26045b', '806c35af-9e12-4c42-972d-1fbc60c0e06a', 1, $bp$Yes, but I was sprinkled, or I was baptized before I believed$bp$, $bp$Oui, mais j'ai été aspergé, ou j'ai été baptisé avant de croire$bp$, 'NEEDS_TALK'),
      ('7cb9141b-a64b-4090-a945-b440ae313cd6', '806c35af-9e12-4c42-972d-1fbc60c0e06a', 2, $bp$No, I have not been baptized yet, but I want to be baptized now$bp$, $bp$Non, je n'ai pas encore été baptisé, mais je veux être baptisé maintenant$bp$, 'NEEDS_TALK'),
      ('83633b50-6594-44bc-95b0-cdaf162531a8', '806c35af-9e12-4c42-972d-1fbc60c0e06a', 3, $bp$No, I am not sure that baptism is needed$bp$, $bp$Non, je ne suis pas sûr que le baptême soit nécessaire$bp$, 'NEEDS_TALK'),
      ('2f7ebdc6-db49-48fe-b8d4-7d506948eb31', '9b5a8031-638b-4922-8082-ed5ca58485fb', 0, $bp$Yes, I have received the Holy Spirit, and I speak in other tongues$bp$, $bp$Oui, j'ai reçu le Saint-Esprit, et je parle en d'autres langues$bp$, 'POSITIVE'),
      ('0872db40-a61e-45d3-abf8-89f20a1a0b04', '9b5a8031-638b-4922-8082-ed5ca58485fb', 1, $bp$I believe I have the Holy Spirit, but I have not yet spoken in other tongues$bp$, $bp$Je crois avoir le Saint-Esprit, mais je n'ai pas encore parlé en d'autres langues$bp$, 'NEEDS_TALK'),
      ('3cbd33a3-39b1-4a2d-bda8-ff4ef01f4aca', '9b5a8031-638b-4922-8082-ed5ca58485fb', 2, $bp$Not yet, but I want to receive Him now$bp$, $bp$Pas encore, mais je veux le recevoir maintenant$bp$, 'NEEDS_TALK'),
      ('09cfe29d-d7d1-4d80-a3c9-600984aec540', '9b5a8031-638b-4922-8082-ed5ca58485fb', 3, $bp$I need someone to explain this to me$bp$, $bp$J'ai besoin que quelqu'un m'explique cela$bp$, 'NEEDS_TALK'),
      ('a1842610-bb6b-4e77-a51f-56bf80e100fd', '9e4ab147-e822-46d7-94e9-d48edf71b265', 0, $bp$I need to be baptized$bp$, $bp$J'ai besoin d'être baptisé$bp$, 'NEEDS_TALK'),
      ('2d5f862c-5c59-4b2c-9e8c-484f696e0751', '9e4ab147-e822-46d7-94e9-d48edf71b265', 1, $bp$I need prayer to receive the Holy Spirit$bp$, $bp$J'ai besoin de prière pour recevoir le Saint-Esprit$bp$, 'NEEDS_TALK'),
      ('aea746c9-8401-4bd8-8f5f-e7fb402b077f', '9e4ab147-e822-46d7-94e9-d48edf71b265', 2, $bp$I need both baptism and prayer for the Holy Spirit$bp$, $bp$J'ai besoin à la fois du baptême et de prière pour le Saint-Esprit$bp$, 'NEEDS_TALK'),
      ('25f9cc76-9168-4d5b-880c-6497d6d4e6d6', '9e4ab147-e822-46d7-94e9-d48edf71b265', 3, $bp$I do not need either, I have both$bp$, $bp$Je n'ai besoin ni de l'un ni de l'autre, j'ai les deux$bp$, 'POSITIVE'),
      ('74055736-14e2-4a71-9bd8-abf0f788b57d', 'ef8af630-c828-467e-a76b-209a31ca31d8', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('d118e639-d133-4071-b2b3-8dc03caa7ba0', 'ef8af630-c828-467e-a76b-209a31ca31d8', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('ebcff539-6cc9-4fe6-ae86-7ff992367973', a_id, 2, 0, 'CHOICE', $bp$Chapter Two says repentance is a change of mind that leads to a change of direction. Have you turned from your old way of living and given your life to Jesus Christ?$bp$, $bp$Le chapitre deux dit que la repentance est un changement d'esprit qui mène à un changement de direction. Vous êtes-vous détourné de votre ancienne manière de vivre et avez-vous donné votre vie à Jésus-Christ ?$bp$, NULL, NULL, $bp$Yes: ask what changed. Not yet, on the way, or not sure: explain that repentance is a decision, not a feeling (Chapter Two). Invite them to pray the Prayer of Repentance from Chapter Two with you.$bp$, $bp$Oui : demandez ce qui a changé. Pas encore, en chemin ou pas sûr : expliquez que la repentance est une décision, pas un sentiment (chapitre deux). Invitez la personne à prier avec vous la prière de repentance du chapitre deux.$bp$, TRUE, FALSE, TRUE),
      ('ba5611c4-cc02-420a-b27d-ff0ec85ec246', a_id, 2, 1, 'CHOICE', $bp$Have you been baptized in water by immersion, going fully under the water and coming back up, after you believed in Jesus?$bp$, $bp$Avez-vous été baptisé d'eau par immersion, en descendant entièrement sous l'eau puis en ressortant, après avoir cru en Jésus ?$bp$, NULL, NULL, $bp$Yes, fully immersed after believing: this is the book's pattern (baptidzo means to immerse; Romans 6:3-4). Sprinkled or baptized before believing: gently explain that the book teaches believer's baptism by immersion, and arrange it. Not yet: do not wait; arrange it as soon as possible, as every example in Acts did.$bp$, $bp$Oui, immergé après avoir cru : c'est le modèle du livre (baptidzo signifie immerger ; Romains 6.3-4). Aspergé ou baptisé avant de croire : expliquez avec douceur que le livre enseigne le baptême du croyant par immersion, et organisez-le. Pas encore : n'attendez pas ; organisez-le dès que possible, comme tous les exemples des Actes.$bp$, TRUE, FALSE, TRUE),
      ('4ae89778-431b-4412-9390-c81e7f17f51d', a_id, 2, 2, 'TEXT', $bp$If yes, when and where were you baptized, and who baptized you?$bp$, $bp$Si oui, quand et où avez-vous été baptisé, et qui vous a baptisé ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('e893a06e-b0d1-4bf6-a7d8-f1bb2a535bfb', a_id, 2, 3, 'CHOICE', $bp$Have you received the Holy Spirit, with the evidence of speaking in other tongues, as in Acts 2, 10 and 19?$bp$, $bp$Avez-vous reçu le Saint-Esprit, avec pour preuve de parler en d'autres langues, comme en Actes 2, 10 et 19 ?$bp$, NULL, NULL, $bp$Yes with tongues: celebrate. Have the Spirit but no tongues, not yet, or need explaining: teach Luke 11:13 (a gift received by asking), and the examples at Pentecost, Cornelius, and Ephesus where they spoke in tongues. Offer to pray with laying on of hands (Acts 8:17; 19:6).$bp$, $bp$Oui avec les langues : réjouissez-vous. A l'Esprit mais pas de langues, pas encore, ou besoin d'explication : enseignez Luc 11.13 (un don reçu en demandant) et les exemples de la Pentecôte, de Corneille et d'Éphèse où ils ont parlé en langues. Proposez de prier avec imposition des mains (Actes 8.17 ; 19.6).$bp$, TRUE, FALSE, TRUE),
      ('4b7c577f-20bf-4098-9ea0-f008f9bd23bb', a_id, 2, 4, 'TEXT', $bp$If yes, when and how did you receive Him?$bp$, $bp$Si oui, quand et comment l'avez-vous reçu ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('ae01b7ad-8089-4e4f-bc94-57b7274c281b', a_id, 2, 5, 'TEXT', $bp$Chapter Two says true repentance produces visible fruit, like Zacchaeus giving back what he took, and Chapter Three says the old life is buried and a new life begins. What has changed in your life and actions since you turned to Christ?$bp$, $bp$Le chapitre deux dit que la vraie repentance produit un fruit visible, comme Zachée rendant ce qu'il avait pris, et le chapitre trois dit que l'ancienne vie est ensevelie et qu'une nouvelle vie commence. Qu'est-ce qui a changé dans votre vie et dans vos actes depuis que vous vous êtes tourné vers Christ ?$bp$, NULL, NULL, $bp$Look for real fruit, as in Zacchaeus: new desire for the Word, freedom, changed habits, something stopped, restored or started. If "nothing yet", have a gentle conversation about what a changed mind should now begin to change.$bp$, $bp$Cherchez un vrai fruit, comme chez Zachée : nouveau désir de la Parole, liberté, habitudes changées, quelque chose arrêté, rendu ou commencé. Si « rien encore », ayez une conversation douce sur ce qu'un esprit changé devrait maintenant commencer à changer.$bp$, TRUE, FALSE, FALSE),
      ('dd6ef360-1367-4a1d-86f8-a3189c465f72', a_id, 2, 6, 'CHOICE', $bp$Would you like the God Nation team to help you with the next step?$bp$, $bp$Aimeriez-vous que l'équipe de God Nation vous aide pour la prochaine étape ?$bp$, NULL, NULL, $bp$This is your follow-up list. Use the contact details to arrange baptism and prayer, as the book promises, through The God Nation Baptism and Holy Spirit group.$bp$, $bp$C'est votre liste de suivi. Utilisez les coordonnées pour organiser le baptême et la prière, comme le livre le promet, par le groupe Baptême et Saint-Esprit de The God Nation.$bp$, TRUE, FALSE, FALSE),
      ('12e208dd-9a2a-473e-a2f3-a04b6a6fcd05', a_id, 2, 7, 'TEXT', $bp$Best way to reach you (phone number or email)$bp$, $bp$Meilleur moyen de vous joindre (numéro de téléphone ou e-mail)$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('eb92f2a1-2421-4673-abad-1d36e16ae500', a_id, 2, 8, 'TEXT', $bp$What is the one thing, if any, that is holding you back from taking the next step in the doorway (repentance, baptism, or the Holy Spirit)? If nothing, write "nothing".$bp$, $bp$Quelle est la seule chose, s'il y en a une, qui vous retient de franchir la prochaine étape de la porte d'entrée (repentance, baptême ou Saint-Esprit) ? S'il n'y a rien, écrivez « rien ».$bp$, NULL, NULL, $bp$Read this with care and pray over it. Name the barrier gently, and answer it from the book. Note them for follow-up.$bp$, $bp$Lisez avec soin et priez à ce sujet. Nommez doucement l'obstacle et répondez-y à partir du livre. Notez la personne pour un suivi.$bp$, TRUE, TRUE, FALSE),
      ('251f5238-7af5-442a-b257-83f1b4aead6c', a_id, 2, 9, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('1884fe5d-005a-48ba-84ae-46f5db707638', 'ebcff539-6cc9-4fe6-ae86-7ff992367973', 0, $bp$Yes, I have turned, and I have received Jesus as my Lord and Saviour$bp$, $bp$Oui, je me suis détourné, et j'ai reçu Jésus comme mon Seigneur et Sauveur$bp$, 'POSITIVE'),
      ('ffbb80f1-a80d-4798-a604-39230cdba8b9', 'ebcff539-6cc9-4fe6-ae86-7ff992367973', 1, $bp$I am on the way, but I have not fully turned yet$bp$, $bp$Je suis en chemin, mais je ne me suis pas encore pleinement détourné$bp$, 'NEEDS_TALK'),
      ('19405b4d-e818-4049-a0ab-ebb1875b6392', 'ebcff539-6cc9-4fe6-ae86-7ff992367973', 2, $bp$Not yet$bp$, $bp$Pas encore$bp$, 'NEEDS_TALK'),
      ('458ffb89-6fdb-4ace-98d2-7ddf9e953d1b', 'ebcff539-6cc9-4fe6-ae86-7ff992367973', 3, $bp$I am not sure what this means for me$bp$, $bp$Je ne suis pas sûr de ce que cela signifie pour moi$bp$, 'NEEDS_TALK'),
      ('ba63056d-c555-4b53-9cfe-a0d2dbbcce6c', 'ba5611c4-cc02-420a-b27d-ff0ec85ec246', 0, $bp$Yes, I was fully immersed in water after I believed$bp$, $bp$Oui, j'ai été entièrement immergé dans l'eau après avoir cru$bp$, 'POSITIVE'),
      ('1b36ae3c-11dd-46fa-b8f8-fbc517d806c7', 'ba5611c4-cc02-420a-b27d-ff0ec85ec246', 1, $bp$Yes, but I was sprinkled, or I was baptized before I believed$bp$, $bp$Oui, mais j'ai été aspergé, ou j'ai été baptisé avant de croire$bp$, 'NEEDS_TALK'),
      ('79d46fbc-8ee3-4fff-bd63-c53b306d14e7', 'ba5611c4-cc02-420a-b27d-ff0ec85ec246', 2, $bp$No, I have not been baptized yet, but I want to be baptized now$bp$, $bp$Non, je n'ai pas encore été baptisé, mais je veux être baptisé maintenant$bp$, 'NEEDS_TALK'),
      ('9b5225d1-6822-4aac-bd65-ba33c5aac9f5', 'ba5611c4-cc02-420a-b27d-ff0ec85ec246', 3, $bp$No, I am not sure that baptism is needed$bp$, $bp$Non, je ne suis pas sûr que le baptême soit nécessaire$bp$, 'NEEDS_TALK'),
      ('63b12a6f-ef49-47f9-a980-ca911d5e02c9', 'e893a06e-b0d1-4bf6-a7d8-f1bb2a535bfb', 0, $bp$Yes, I have received the Holy Spirit, and I speak in other tongues$bp$, $bp$Oui, j'ai reçu le Saint-Esprit, et je parle en d'autres langues$bp$, 'POSITIVE'),
      ('cd05e294-bcc6-49e2-a304-aba2a008e11a', 'e893a06e-b0d1-4bf6-a7d8-f1bb2a535bfb', 1, $bp$I believe I have the Holy Spirit, but I have not yet spoken in other tongues$bp$, $bp$Je crois avoir le Saint-Esprit, mais je n'ai pas encore parlé en d'autres langues$bp$, 'NEEDS_TALK'),
      ('4fc62fef-2ae5-465b-9a12-39a1cce9de07', 'e893a06e-b0d1-4bf6-a7d8-f1bb2a535bfb', 2, $bp$Not yet, but I want to receive Him now$bp$, $bp$Pas encore, mais je veux le recevoir maintenant$bp$, 'NEEDS_TALK'),
      ('c37db92b-1966-4c52-88ea-7ae3c0483079', 'e893a06e-b0d1-4bf6-a7d8-f1bb2a535bfb', 3, $bp$I need someone to explain this to me$bp$, $bp$J'ai besoin que quelqu'un m'explique cela$bp$, 'NEEDS_TALK'),
      ('535853af-1c2f-47f5-8781-565d9239f34f', 'dd6ef360-1367-4a1d-86f8-a3189c465f72', 0, $bp$I need to be baptized$bp$, $bp$J'ai besoin d'être baptisé$bp$, 'NEEDS_TALK'),
      ('1c301204-b681-472b-879c-388e470dabe2', 'dd6ef360-1367-4a1d-86f8-a3189c465f72', 1, $bp$I need prayer to receive the Holy Spirit$bp$, $bp$J'ai besoin de prière pour recevoir le Saint-Esprit$bp$, 'NEEDS_TALK'),
      ('0fa2fa2c-aa1a-47d8-a9b8-12150e4b291d', 'dd6ef360-1367-4a1d-86f8-a3189c465f72', 2, $bp$I need both baptism and prayer for the Holy Spirit$bp$, $bp$J'ai besoin à la fois du baptême et de prière pour le Saint-Esprit$bp$, 'NEEDS_TALK'),
      ('b451a07e-8feb-4517-9e4f-7b442046e271', 'dd6ef360-1367-4a1d-86f8-a3189c465f72', 3, $bp$I do not need either, I have both$bp$, $bp$Je n'ai besoin ni de l'un ni de l'autre, j'ai les deux$bp$, 'POSITIVE'),
      ('8c7ee893-ffde-4376-ad74-d972a9cefca3', '251f5238-7af5-442a-b257-83f1b4aead6c', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('03d350c3-c1ba-4851-b244-8bd8febc5477', '251f5238-7af5-442a-b257-83f1b4aead6c', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
