      ('cc662a64-787d-461c-9d95-5e82fade6796', 'c7335d36-d6a6-43d4-bcf0-2e63921bcee6', 2, $bp$Not yet, but I want to receive Him now$bp$, $bp$Pas encore, mais je veux le recevoir maintenant$bp$, 'NEEDS_TALK'),
