  END IF;

  IF EXISTS (SELECT 1 FROM "Question" WHERE "assessmentId" = a_id AND "setNumber" = 3) THEN
    DELETE FROM "PersonalQuestion" WHERE "assessmentId" = a_id AND "setNumber" = 3;

